function inferSeverityFromCode(system: string, subsystem: string): OBDEntry['severity'] {
  if (system === 'P') {
    if (subsystem === '3') return 'high';           // misfires
    if (subsystem === '6') return 'medium';         // computer circuits
    if (['7','8','9'].includes(subsystem)) return 'high'; // transmission
    if (['A','B','C','D','E','F'].includes(subsystem)) return 'high'; // hybrid
  }
  if (system === 'B') {
    if (['0','1'].includes(subsystem)) return 'critical'; // airbags
  }
  if (system === 'C') {
    if (['0','1'].includes(subsystem)) return 'high';  // brakes
    if (['4'].includes(subsystem)) return 'medium';    // stability
  }
  if (system === 'U') {
    if (['0','1'].includes(subsystem)) return 'high';  // CAN bus
  }
  return 'medium';
}

function inferCanDrive(system: string, subsystem: string): boolean {
  if (system === 'P') {
    if (subsystem === '3') return false;   // misfires
    if (['7','8','9'].includes(subsystem)) return false; // transmission
  }
  if (system === 'B') {
    if (['0','1'].includes(subsystem)) return false; // airbags
  }
  if (system === 'C') {
    if (['0','1'].includes(subsystem)) return false; // brakes/ABS
  }
  if (system === 'U') {
    if (['0','1'].includes(subsystem)) return false; // CAN bus loss
  }
  return true;
}

export function decodeOBDStructure(code: string): OBDEntry | null {
  const c = code.trim().toUpperCase();
  // Must be 5 chars: [P|B|C|U][0-3][0-9A-F][0-9A-F][0-9A-F]
  if (!/^[PBCU][0-3][0-9A-F]{3}$/i.test(c)) return null;

  const system = c[0];
  const typeDigit = c[1];
  const subsystem = c[2].toUpperCase();
  const specific = c.slice(3);

  const systemMap: Record<string, Record<string, string>> = {
    P: SUBSYSTEM_P, B: SUBSYSTEM_B, C: SUBSYSTEM_C, U: SUBSYSTEM_U,
  };
  const systemNames: Record<string, string> = {
    P: 'Powertrain', B: 'Body', C: 'Chassis', U: 'Network/Communications',
  };

  const subsystemDesc = systemMap[system]?.[subsystem] ?? 'Vehicle Systems';
  const typeName = TYPE_LABELS[typeDigit] ?? 'Standard';
  const systemName = systemNames[system];

  const title = `${typeName} ${systemName} Fault — ${subsystemDesc}`;
  const description =
    `Code ${c} is a ${typeName.toLowerCase()} ${systemName.toLowerCase()} diagnostic trouble code in the "${subsystemDesc}" subsystem. ` +
    `This code was not found in the local database but its structure indicates a fault in the ${subsystemDesc} area. ` +
    `Search for "${c}" on alldata.com, identifix.com, or your vehicle's factory service manual for vehicle-specific diagnosis. ` +
    `The specific fault number is ${specific}, and the full code follows SAE J2012 OBD-II naming conventions.`;

  return {
    code: c,
    title,
    description,
    severity: inferSeverityFromCode(system, subsystem),
    likelyCauses: [
      `Fault in the ${subsystemDesc} system`,
      'Wiring or connector issue in related circuit',
      'Failed sensor or actuator in this subsystem',
      `${typeName === 'Manufacturer-Specific' ? 'Vehicle-specific component — check manufacturer TSBs' : 'Related control module fault'}`,
    ],
    estimatedRepairCost: 'Varies — professional diagnosis recommended',
    partsNeeded: [],
    canDrive: inferCanDrive(system, subsystem),
    diyInstructions: {
      feasibility: 'Professional diagnosis recommended for unlisted codes',
      tools: ['OBD-II scanner', 'Multimeter', 'Factory service manual or AllData subscription'],
      steps: [
        `Research code ${c} on alldata.com, identifix.com, or the NHTSA database for your specific year/make/model`,
        'Check for any Technical Service Bulletins (TSBs) from the manufacturer related to this code',
        `Inspect the ${subsystemDesc.toLowerCase()} circuits, connectors, and components for obvious damage`,
        'Clear the code and perform a test drive to confirm if it is a hard fault or intermittent',
        'If the code returns, professional diagnosis with factory scan tool is recommended',
      ],
      savings: 'Varies',
    },
  };
}

export const isSmartDecodedEntry = (code: string): boolean => {
  const normalized = code.trim().toUpperCase();
  return !(normalized in OBD_DATABASE) && /^[PBCU][0-3][0-9A-F]{3}$/i.test(normalized);
};

export const lookupOBDCode = (code: string): OBDEntry | null => {
  const normalized = code.trim().toUpperCase();
  // 1. Try explicit database first
  if (OBD_DATABASE[normalized]) return OBD_DATABASE[normalized];
  // 2. Fall back to structural decoder for any valid OBD-II code
  return decodeOBDStructure(normalized);
};

export const searchOBDCodes = (query: string): OBDEntry[] => {
  const q = query.toLowerCase();
  return Object.values(OBD_DATABASE).filter(entry =>
    entry.code.toLowerCase().includes(q) ||
    entry.title.toLowerCase().includes(q) ||
    entry.description.toLowerCase().includes(q)
  );
};
